const listRetriableInboundWebhooks = `-- name: ListRetriableInboundWebhooks :many
SELECT organization_id, id, source, integration_id, code, event_type, payload, signature, status, attempts, processing_at, created_at, updated_at FROM inbound_webhooks
WHERE organization_id = $1
  AND status <> 'succeeded'
  AND (CASE
    WHEN status = 'pending' AND processing_at IS NULL THEN created_at
    ELSE COALESCE(processing_at, created_at) + $2::interval
  END) <= created_at + $3::interval
  AND (CASE
    WHEN status = 'pending' AND processing_at IS NULL THEN created_at
    ELSE COALESCE(processing_at, created_at) + $2::interval
  END) <= $4::timestamptz
ORDER BY id
`

type ListRetriableInboundWebhooksParams struct {
	OrganizationID uuid.UUID
	RetryInterval  pgtype.Interval
	RetryWindow    pgtype.Interval
	Now            time.Time
}

// Mirrors payment.InboundWebhook.NextRetry: a never-attempted pending
// webhook is due at reception, any other unfinished one retry_interval
// after its last attempt (or reception), as long as that falls within
// retry_window of reception.
func (q *Queries) ListRetriableInboundWebhooks(ctx context.Context, arg ListRetriableInboundWebhooksParams) ([]InboundWebhook, error) {
	rows, err := q.db.Query(ctx, listRetriableInboundWebhooks,
		arg.OrganizationID,
		arg.RetryInterval,
		arg.RetryWindow,
		arg.Now,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []InboundWebhook{}
	for rows.Next() {
		var i InboundWebhook
		if err := rows.Scan(
			&i.OrganizationID,
			&i.ID,
			&i.Source,
			&i.IntegrationID,
			&i.Code,
			&i.EventType,
			&i.Payload,
			&i.Signature,
			&i.Status,
			&i.Attempts,
			&i.ProcessingAt,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

